<script setup lang="ts">import {onMounted,onUnmounted,ref} from 'vue';const el=ref<HTMLElement|null>(null),visible=ref(false);let observer:IntersectionObserver|undefined;onMounted(()=>{if(typeof IntersectionObserver==='undefined'){visible.value=true;return}observer=new IntersectionObserver(entries=>{if(entries[0]?.isIntersecting){visible.value=true;observer?.disconnect()}},{threshold:0.1});if(el.value)observer.observe(el.value)});onUnmounted(()=>observer?.disconnect());</script><template><div ref="el" class="vx-reveal" :class="{'vx-reveal--visible':visible}"><slot/></div></template>